"use client";
import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import axios from "axios";
import cookies from "js-cookie";

export default function EncadrantProfile() {
  const { user_id } = useParams();
  const [encadrant, setEncadrant] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchEncadrantData = async () => {
      try {
        const token = cookies.get("token");
        if (!token) {
          throw new Error("Non autorisé. Veuillez vous connecter.");
        }

        const response = await axios.get(
          `http://localhost:5000/api/Encadrants/${user_id}`,
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );

        if (!response.data) {
          throw new Error("Aucune donnée reçue");
        }

        setEncadrant(response.data);
      } catch (err) {
        console.error("Erreur lors de la récupération des données :", err);
        setError(err.response?.data?.message || err.message);
      } finally {
        setLoading(false);
      }
    };

    if (user_id) {
      fetchEncadrantData();
    }
  }, [user_id]);

  if (loading) return <p className="text-center mt-10 text-gray-500">Chargement...</p>;
  if (error) return <p className="text-red-500 text-center mt-10">{error}</p>;
  if (!encadrant) return <p className="text-center mt-10 text-gray-500">Aucune information trouvée.</p>;

  // Diviser les sujets en deux catégories
  const sujetsAvecGroupes = encadrant.sujets.filter(sujet => sujet.groupes.length > 0);
  const sujetsSansGroupes = encadrant.sujets.filter(sujet => sujet.groupes.length === 0);

  return (
    <div className="max-w-4xl mx-auto p-6 bg-white shadow-lg rounded-lg mt-10">
      <h1 className="text-3xl font-bold text-center text-blue-700 mb-6">
        Profil Encadrant
      </h1>

      {/* Informations personnelles */}
      <div className="bg-gray-100 p-5 rounded-lg shadow-md mb-6">
        <h2 className="text-xl font-semibold text-gray-700 mb-3">Informations générales</h2>
        <p><strong>Nom :</strong> {encadrant.nom}</p>
        <p><strong>Prénom :</strong> {encadrant.prenom}</p>
        <p><strong>Email :</strong> {encadrant.email}</p>
        <p><strong>Année :</strong> {encadrant.annee}</p>
      </div>

      {/* Affichage des sujets avec des groupes */}
      {sujetsAvecGroupes.length > 0 && (
        <div>
          <h2 className="text-2xl font-semibold text-blue-700 mb-6">Sujets avec Groupes</h2>
          {sujetsAvecGroupes.map((sujet) => (
            <div key={sujet.idSujet} className="mb-8">
              <h3 className="text-xl font-bold text-gray-700 mb-4">
                Sujet: {sujet.titre}
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {sujet.groupes.map((groupe) => (
                  <div key={groupe.idGroupe} className="bg-blue-50 p-5 rounded-lg shadow-md">
                    <h4 className="text-lg font-semibold text-blue-700 mb-2">
                      Groupe: {groupe.nomGroupe}
                    </h4>
                    <p><strong>Tuteur :</strong> {groupe.tuteur ? `${groupe.tuteur.nom} ${groupe.tuteur.prenom}` : "Aucun"}</p>
                    <div>
                      <h5 className="font-semibold text-blue-600">Étudiants :</h5>
                      <ul className="list-disc pl-6">
                        {groupe.etudiants.length > 0 ? (
                          groupe.etudiants.map((etudiant, index) => (
                            <li key={index}>{etudiant.nom} {etudiant.prenom}</li>
                          ))
                        ) : (
                          <li className="text-gray-500">Aucun étudiant</li>
                        )}
                      </ul>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Affichage des sujets sans groupes */}
      {sujetsSansGroupes.length > 0 && (
        <div>
          <h2 className="text-2xl font-semibold text-blue-700 mb-6">Sujets sans Groupes</h2>
          {sujetsSansGroupes.map((sujet) => (
            <div key={sujet.idSujet} className="mb-8">
              <h3 className="text-xl font-bold text-gray-700 mb-4">
                Sujet: {sujet.titre}
              </h3>
              <p className="text-gray-500">Aucun groupe assigné.</p>
            </div>
          ))}
        </div>
      )}

      {/* Message si aucun sujet n'est trouvé */}
      {encadrant.sujets.length === 0 && (
        <p className="text-center text-gray-500">Aucun sujet trouvé.</p>
      )}
    </div>
  );
}